package org.jlinalg.cli;

import static org.junit.jupiter.api.Assertions.*;
import java.io.ByteArrayOutputStream;
import java.io.PrintStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class FumaReferenceCliTest {
    @TempDir Path temp;
    private static final List<String> PAYLOAD=List.of("variants.tsv","samples.tsv","sample-selection.tsv","genotypes.bin","reference.tsv","variant-audit.tsv","ld.tsv","ld-audit.tsv");
    private static byte[] pack(int... calls){byte[] r=new byte[(calls.length+3)/4];for(int i=0;i<calls.length;i++){int c=switch(calls[i]){case -1->1;case 0->3;case 1->2;case 2->0;default->throw new IllegalArgumentException();};r[i/4]|=(byte)(c<<(2*(i%4)));}return r;}
    private void inputs()throws Exception{
        Files.writeString(temp.resolve("panel.fam"),"F A 0 0 1 -9\nF B 0 0 2 -9\nF C 0 0 0 -9\nF D 0 0 1 -9\nF E A B 2 -9\n");
        Files.writeString(temp.resolve("panel.bim"),"1 rs0 0 1101 G A\n1 rs1 0 100 G A\n1 rs2 0 1100 G A\n1 zero 0 2000 G A\n1 hetero 0 2100 G A\n1 missing 0 2200 G A\n");
        try(var bed=Files.newOutputStream(temp.resolve("panel.bed"))){bed.write(new byte[]{0x6c,0x1b,1});for(int i=0;i<3;i++)bed.write(pack(0,1,2,1,2));bed.write(pack(0,0,0,0,2));bed.write(pack(1,1,1,1,0));bed.write(pack(-1,-1,-1,-1,1));}
        Files.writeString(temp.resolve("variants.tsv"),"id\nmissing\nrs2\nzero\nrs1\nhetero\nrs0\n");Files.writeString(temp.resolve("samples.tsv"),"fid\tiid\nF\tE\nF\tC\nF\tA\nF\tD\nF\tB\n");
    }
    private List<String> args(String output)throws Exception{inputs();return new ArrayList<>(List.of("--method","prepare-reference","--bfile",temp.resolve("panel").toString(),"--variants",temp.resolve("variants.tsv").toString(),"--samples",temp.resolve("samples.tsv").toString(),"--sample-policy","founders","--assembly","synthetic-GRCh37","--population","declared-synthetic","--release","local-v1","--minimum-maf","0","--ld-floor",".05","--window-bp","1000","--window-index-gap","1","--out",temp.resolve(output).toString()));}
    private int run(List<String> args){var errors=new ByteArrayOutputStream();int code=JLinAlgCli.run(concat("fuma-tools",args),new PrintStream(new ByteArrayOutputStream()),new PrintStream(errors));if(code!=0)assertTrue(errors.toString().contains("ANALYSIS FAILED")||errors.toString().contains("WORKFLOW FAILED"),errors.toString());return code;}
    private static String[] concat(String first,List<String> rest){List<String> a=new ArrayList<>(List.of(first));a.addAll(rest);return a.toArray(String[]::new);}
    private static void set(List<String> args,String name,String value){args.set(args.indexOf("--"+name)+1,value);}
    private List<String> replay(String input,String output){return new ArrayList<>(List.of("--method","replay-reference","--bundle",temp.resolve(input).toString(),"--out",temp.resolve(output).toString()));}
    private void copy(String from,String to)throws Exception{Path dest=Files.createDirectory(temp.resolve(to));for(String name:PAYLOAD)Files.copy(temp.resolve(from).resolve(name),dest.resolve(name));Files.copy(temp.resolve(from).resolve("reference-bundle.json"),dest.resolve("reference-bundle.json"));}
    private Map<String,Object> carrier(String name)throws Exception{Map<String,Object> result=new LinkedHashMap<>();AdmixtureInputs.json(temp.resolve(name+"/reference-bundle.json"),1048576).forEach((k,v)->result.put(k.toString(),v));return result;}
    private void save(String name,Map<String,Object> m)throws Exception{Files.writeString(temp.resolve(name+"/reference-bundle.json"),RegenieRuntime.json(m)+"\n");}
    private void reseal(String name,String file)throws Exception{var m=carrier(name);var payload=new LinkedHashMap<Object,Object>((Map<?,?>)m.get("payload"));Path p=temp.resolve(name).resolve(file);payload.put(file,Map.of("bytes",Files.size(p),"sha256",FollowupSupport.hash(p)));m.put("payload",payload);save(name,m);}
    private void failed(String name,String message)throws Exception{Path out=temp.resolve(name);assertFalse(Files.exists(out.resolve("reference-bundle.json")));assertTrue(Files.readString(out.resolve("WARNINGS.md")).contains(message));assertTrue(Files.readString(out.resolve("analysis-status.json")).contains("failed"));assertTrue(Files.isDirectory(out.resolve("partial")));}
    @Test void prepareCapturesAllRequestedCallsAndExplicitFounderSelection()throws Exception{
        assertEquals(0,run(args("capture")));Path d=temp.resolve("capture");assertEquals(6,Files.readAllLines(d.resolve("variants.tsv")).size()-1);assertEquals(3,Files.readAllLines(d.resolve("reference.tsv")).size()-1);assertEquals(4,Files.readAllLines(d.resolve("samples.tsv")).size()-1);assertTrue(Files.readString(d.resolve("sample-selection.tsv")).contains("4\tF\tE\tfalse\t2\ttrue\tfalse"));String audit=Files.readString(d.resolve("variant-audit.tsv"));for(String s:List.of("ZERO_MAF","CONSTANT_CALLS","NO_OBSERVED_CALLS"))assertTrue(audit.contains(s));assertEquals(22,Files.size(d.resolve("genotypes.bin")));assertTrue(Files.readString(d.resolve("ld.tsv")).contains("100\t1100\t1.0"));assertFalse(Files.readString(d.resolve("ld.tsv")).lines().anyMatch(s->s.startsWith("1\t100\t1101\t")));assertTrue(Files.readString(d.resolve("WARNINGS.md")).contains("uncomputed"));assertTrue(Files.readString(d.resolve("session.json")).contains("locus_ready\":true"));
    }
    @Test void replayIsPortableAfterOriginalInputsAreRemoved()throws Exception{
        assertEquals(0,run(args("producer")));copy("producer","portable-α");for(String f:List.of("panel.fam","panel.bim","panel.bed","variants.tsv","samples.tsv"))Files.delete(temp.resolve(f));assertEquals(0,run(replay("portable-α","replayed")));for(String f:PAYLOAD)assertEquals(-1,Files.mismatch(temp.resolve("producer").resolve(f),temp.resolve("replayed").resolve(f)),f);assertEquals(0,run(replay("replayed","replayed-again")));
    }
    @Test void selectedPolicyIncludesChildRatherThanInferringFounderRestriction()throws Exception{var a=args("all-selected");set(a,"sample-policy","selected");assertEquals(0,run(a));assertEquals(5,Files.readAllLines(temp.resolve("all-selected/samples.tsv")).size()-1);String audit=Files.readString(temp.resolve("all-selected/variant-audit.tsv"));assertTrue(audit.contains("zero\t1\t2000\t5\t0\t2\t8\t0.2\t0.2\tALLELE1\tDEFINED\tRETAINED"));assertEquals(0,run(replay("all-selected","all-selected-replay")));}
    @Test void everyPayloadHashAndMissingFileIsChecked()throws Exception{assertEquals(0,run(args("base")));for(int i=0;i<PAYLOAD.size();i++){String f=PAYLOAD.get(i),bad="tampered-"+i,out="failure-"+i;copy("base",bad);Files.write(temp.resolve(bad).resolve(f),new byte[]{33},java.nio.file.StandardOpenOption.APPEND);assertEquals(2,run(replay(bad,out)));failed(out,"integrity");}copy("base","missing");Files.delete(temp.resolve("missing/ld.tsv"));assertEquals(2,run(replay("missing","missing-result")));failed("missing-result","Regular non-symlink");}
    @Test void rehashedScientificOutputStillFailsCompleteReplay()throws Exception{assertEquals(0,run(args("base")));for(String f:List.of("reference.tsv","ld.tsv","variant-audit.tsv","ld-audit.tsv")){String name=f.replace('.','-');copy("base",name);Path p=temp.resolve(name).resolve(f);Files.writeString(p,Files.readString(p).replace("1.0","0.9")+"forged\n");reseal(name,f);assertEquals(2,run(replay(name,name+"-result")));failed(name+"-result","replay differs");}}
    @Test void rehashedPackedPaddingAndTruncationAreRejected()throws Exception{assertEquals(0,run(args("base")));var all=args("five");set(all,"sample-policy","selected");assertEquals(0,run(all));copy("five","padding");Path p=temp.resolve("padding/genotypes.bin");byte[] bytes=Files.readAllBytes(p);bytes[17]|=(byte)0x80;Files.write(p,bytes);reseal("padding","genotypes.bin");assertEquals(2,run(replay("padding","padding-result")));failed("padding-result","padding");copy("base","truncated");p=temp.resolve("truncated/genotypes.bin");bytes=Files.readAllBytes(p);Files.write(p,java.util.Arrays.copyOf(bytes,bytes.length-1));reseal("truncated","genotypes.bin");assertEquals(2,run(replay("truncated","truncated-result")));failed("truncated-result","truncation");}
    @Test void forgedSelectionProtocolAndAccountingCannotAuthorizeHandoff()throws Exception{
        assertEquals(0,run(args("base")));copy("base","selection");Path p=temp.resolve("selection/sample-selection.tsv");Files.writeString(p,Files.readString(p).replace("4\tF\tE\tfalse\t2\ttrue\tfalse","4\tF\tE\tfalse\t2\ttrue\ttrue"));reseal("selection","sample-selection.tsv");assertEquals(2,run(replay("selection","selection-result")));failed("selection-result","selection disagrees");
        copy("base","protocol");var m=carrier("protocol");var protocol=new LinkedHashMap<Object,Object>((Map<?,?>)m.get("protocol"));protocol.put("window-bp","0");m.put("protocol",protocol);save("protocol",m);assertEquals(2,run(replay("protocol","protocol-result")));failed("protocol-result","replay differs");
        copy("base","accounting");m=carrier("accounting");var accounting=new LinkedHashMap<Object,Object>((Map<?,?>)m.get("accounting"));accounting.put("assessed_pairs",999);m.put("accounting",accounting);save("accounting",m);assertEquals(2,run(replay("accounting","accounting-result")));failed("accounting-result","accounting disagrees");
    }
    @Test void unknownOrDuplicateIdsAndNoEligibleSamplesAreExplicitFailures()throws Exception{
        for(int i=0;i<4;i++){String name="bad-selection-"+i;var a=args(name);if(i==0)Files.writeString(temp.resolve("variants.tsv"),"id\nabsent\n");if(i==1)Files.writeString(temp.resolve("samples.tsv"),"fid\tiid\nF\tA\nF\tA\n");if(i==2)Files.writeString(temp.resolve("samples.tsv"),"fid\tiid\nunknown\tA\n");if(i==3)Files.writeString(temp.resolve("samples.tsv"),"fid\tiid\nF\tE\n");assertEquals(2,run(a));failed(name,"ANALYSIS FAILED");}
    }
    @Test void undefinedPairFailsWithRetainedAuditAndNoReferenceCarrier()throws Exception{
        var a=args("undefined");Files.writeString(temp.resolve("variants.tsv"),"id\nrs0\nrs1\n");try(var bed=Files.newOutputStream(temp.resolve("panel.bed"))){bed.write(new byte[]{0x6c,0x1b,1});bed.write(pack(0,0,1,-1,0));bed.write(pack(0,1,-1,2,0));for(int i=0;i<4;i++)bed.write(pack(0,1,2,1,0));}set(a,"window-bp","10000");assertEquals(2,run(a));failed("undefined","Undefined eligible LD pair");assertTrue(Files.readString(temp.resolve("undefined/partial/ld-audit.tsv")).contains("CONSTANT_SECOND"));assertTrue(Files.exists(temp.resolve("undefined/partial/variant-audit.tsv")));
    }
    @Test void resourceFailuresAndExistingDestinationNeverPublishPartialSuccess()throws Exception{
        for(String[] cap:new String[][]{{"max-pairs","1"},{"max-word-work","1"},{"max-owned-bytes","65536"},{"max-output-bytes","40"},{"max-metadata-bytes","16"}}){String name="budget-"+cap[0];var a=args(name);a.addAll(List.of("--"+cap[0],cap[1]));assertEquals(2,run(a));failed(name,"ANALYSIS FAILED");}var a=args("existing");Files.createDirectory(temp.resolve("existing"));Files.writeString(temp.resolve("existing/keep"),"untouched");assertEquals(2,run(a));assertEquals("untouched",Files.readString(temp.resolve("existing/keep")));
    }
    private List<String> loci(String bundle,String output)throws Exception{
        Files.writeString(temp.resolve("gwas.tsv"),"chr\tpos\tnon_effect_allele\teffect_allele\trsID\tp\n1\t100\tA\tG\trs1\t1e-10\n1\t1101\tA\tG\trs0\t2e-10\n");
        return new ArrayList<>(List.of("--method","loci","--reference-bundle",temp.resolve(bundle).toString(),"--gwas",temp.resolve("gwas.tsv").toString(),"--lead-p","5e-8","--candidate-p",".05","--maf","0","--independent-r2",".6","--lead-r2",".1","--merge-distance-bp","0","--merge-boundary","strict","--include-reference","false","--mhc","none","--add-independent","true","--ties","position","--unmatched-reference","error","--empty","error","--out",temp.resolve(output).toString()));
    }
    @Test void locusHandoffReplaysAndCarriesUncomputedWindowWithoutTreatingItAsZero()throws Exception{assertEquals(0,run(args("base")));assertEquals(0,run(loci("base","loci")));Path p=temp.resolve("loci");assertEquals(3,Files.readAllLines(p.resolve("independent.tsv")).size());assertTrue(Files.readString(p.resolve("session.json")).contains("reference_preparation_replayed\":true"));String w=Files.readString(p.resolve("WARNINGS.md"));assertTrue(w.contains("uncomputed"));assertTrue(w.contains("biological independence"));}
    @Test void locusHandoffRejectsRehashedFalseSparseDataAndProtocolOverride()throws Exception{assertEquals(0,run(args("base")));copy("base","bad");Files.writeString(temp.resolve("bad/ld.tsv"),"chr\tpos1\tpos2\tr2\n");reseal("bad","ld.tsv");assertEquals(2,run(loci("bad","bad-loci")));assertFalse(Files.exists(temp.resolve("bad-loci/loci.tsv")));assertTrue(Files.readString(temp.resolve("bad-loci/WARNINGS.md")).contains("replay disagrees"));var a=loci("base","override");a.addAll(List.of("--window-bp","0"));assertEquals(2,run(a));assertFalse(Files.exists(temp.resolve("override")));}
    @Test void rawWindowFlagsArePairedAndLegacyRawModeStillRuns()throws Exception{
        assertEquals(0,run(args("base")));var a=loci("base","raw");a.remove(a.indexOf("--reference-bundle")+1);a.remove("--reference-bundle");a.addAll(List.of("--reference",temp.resolve("base/reference.tsv").toString(),"--ld",temp.resolve("base/ld.tsv").toString(),"--reference-id","explicit-synthetic","--ld-floor",".05","--window-bp","1000","--window-index-gap","1"));assertEquals(0,run(a));set(a,"out",temp.resolve("single-window").toString());a.remove(a.indexOf("--window-index-gap")+1);a.remove("--window-index-gap");assertEquals(2,run(a));a.remove(a.indexOf("--window-bp")+1);a.remove("--window-bp");set(a,"out",temp.resolve("legacy").toString());assertEquals(0,run(a));
    }
    @Test void commandRoutingHelpAndReplayOverridesAreExplicit()throws Exception{for(String method:List.of("prepare-reference","replay-reference"))assertEquals(0,run(List.of("--method",method,"--help")));assertEquals(2,run(List.of("--method","prepare-reference","--unknown","x")));var a=replay("unused","unused");a.addAll(List.of("--ld-floor",".1"));assertEquals(2,run(a));}
    private Map<String,String> map(List<String> args){var m=new LinkedHashMap<String,String>();for(int i=0;i<args.size();i+=2)m.put(args.get(i).substring(2),args.get(i+1));m.remove("method");m.remove("out");return m;}
    private Map<String,Object> workflow()throws Exception{var preparation=map(args("unused"));for(String k:List.of("bfile","variants","samples"))preparation.put(k,Path.of(preparation.get(k)).getFileName().toString());var loci=map(loci("unused","unused"));loci.remove("reference-bundle");loci.put("gwas","gwas.tsv");return new LinkedHashMap<>(Map.of("schema_version",1,"build","synthetic-GRCh37","reference_prepare",preparation,"loci",loci));}
    private int workflowRun(Map<String,Object> root,String output)throws Exception{Path recipe=temp.resolve("workflow-"+output+".json");Files.writeString(recipe,RegenieRuntime.json(root));return run(List.of("--method","workflow","--workflow-options-file",recipe.toString(),"--out",temp.resolve(output).toString()));}
    @Test void typedWorkflowPreparesReplaysAndPassesWindowsToLoci()throws Exception{assertEquals(0,workflowRun(workflow(),"workflow"));Path d=temp.resolve("workflow");assertTrue(Files.exists(d.resolve("reference-preparation/reference-bundle.json")));assertTrue(Files.exists(d.resolve("loci/loci.tsv")));assertTrue(Files.readString(d.resolve("loci/session.json")).contains("reference_preparation_replayed\":true"));assertTrue(Files.readString(d.resolve("manifest.json")).contains("reference-preparation"));}
    @Test void failedPreparationSkipsDependentLociWithProminentRecovery()throws Exception{var root=workflow();Files.writeString(temp.resolve("variants.tsv"),"id\nabsent\n");assertEquals(2,workflowRun(root,"workflow-fail"));Path d=temp.resolve("workflow-fail");assertFalse(Files.exists(d.resolve("loci/loci.tsv")));assertTrue(Files.readString(d.resolve("loci/WARNINGS.md")).contains("Required stage reference-preparation did not complete"));assertTrue(Files.readString(d.resolve("WARNINGS.md")).contains("Required action"));}
    @Test void workflowRejectsConflictingReferenceAndBuildDeclarations()throws Exception{var root=workflow();Map<?,?> prep=(Map<?,?>)root.get("reference_prepare");var bad=new LinkedHashMap<Object,Object>(prep);bad.put("assembly","different");root.put("reference_prepare",bad);assertEquals(2,workflowRun(root,"bad-build"));assertFalse(Files.exists(temp.resolve("bad-build")));root=workflow();var locus=new LinkedHashMap<Object,Object>((Map<?,?>)root.get("loci"));locus.put("ld-floor","0");root.put("loci",locus);assertEquals(2,workflowRun(root,"bad-handoff"));assertFalse(Files.exists(temp.resolve("bad-handoff")));}
    @Test void bundleAssemblyAssertionCannotRelabelCoordinates()throws Exception{assertEquals(0,run(args("base")));var a=loci("base","wrong-assembly");a.addAll(List.of("--expected-reference-assembly","GRCh38"));assertEquals(2,run(a));assertFalse(Files.exists(temp.resolve("wrong-assembly/loci.tsv")));assertTrue(Files.readString(temp.resolve("wrong-assembly/WARNINGS.md")).contains("no liftover"));}
}
